code = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(grid[rr][cc] == 3 for rr in range(r-1, r+2) for cc in range(c-1, c+2) if (rr,cc) != (r,c)):
                centers.append((r,c))
    vlines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= max(5, h-3)]
    hlines = [r for r in range(h) if sum(grid[r][c] == 2 for c in range(w)) >= max(5, w-3)]
    for r,c in centers:
        if vlines:
            # A vertical 2-divider projects the mark horizontally.
            for x in range(w):
                if out[r][x] not in (2,3): out[r][x] = 1
            for x in vlines:
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        rr,cc=r+dr,x+dc
                        if 0 <= rr < h and 0 <= cc < w and (dr or dc) and out[rr][cc] != 3:
                            out[rr][cc]=1
        elif hlines:
            # A horizontal 2-divider projects the mark vertically.
            for y in range(h):
                if out[y][c] not in (2,3): out[y][c] = 1
            for y in hlines:
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        rr,cc=y+dr,c+dc
                        if 0 <= rr < h and 0 <= cc < w and (dr or dc) and out[rr][cc] != 3:
                            out[rr][cc]=1
    return out
'''
